SELECT CASE WHEN p.price >= 1350 THEN 'high' WHEN p.price >= 380 THEN 'mid' ELSE 'low' END AS price_bucket, CASE WHEN p.brand IN ('Umbrella', 'Initech') THEN 'core' ELSE 'other' END AS brand_group, ROUND(STDDEV(ss.revenue), 2) AS stddev_revenue, MIN(ss.sale_date) AS first_sale_date FROM store_sales ss INNER JOIN products p ON ss.product_id = p.id LEFT JOIN stores s ON ss.store_id = s.id WHERE s.city = 'New York' GROUP BY CASE WHEN p.price >= 1350 THEN 'high' WHEN p.price >= 380 THEN 'mid' ELSE 'low' END, CASE WHEN p.brand IN ('Umbrella', 'Initech') THEN 'core' ELSE 'other' END;
